    #[test]
    fn replay_truncates_partial_turn() {
        let dir = tmp_working_dir();
        let mut mgr = SessionManager::new(&dir);
        let session = mgr
            .create("replay-partial", "deepseek-chat", "p")
            .expect("create");
        let now = Utc::now();

        write_log(
            session,
            &[
                // Turn 1: complete
                LogEntry::user_input(now, 1, "hi".into()),
                LogEntry::llm_prompt(
                    now,
                    1,
                    "d".into(),
                    "m".into(),
                    serde_json::json!([]),
                    serde_json::json!([]),
                ),
                LogEntry::llm_response(
                    now,
                    1,
                    Some("m1".into()),
                    Some("hello".into()),
                    None,
                    None,
                    UsageData {
                        input_tokens: 5,
                        output_tokens: 3,
                    },
                ),
                LogEntry::turn_complete(now, 1, "hello".into(), 0),
                // Turn 2: incomplete (crash after user input, no turn_complete)
                LogEntry::user_input(now, 2, "unfinished".into()),
                LogEntry::llm_prompt(
                    now,
                    2,
                    "d".into(),
                    "m".into(),
                    serde_json::json!([]),
                    serde_json::json!([]),
                ),
                LogEntry::llm_response(
                    now,
                    2,
                    Some("m2".into()),
                    Some("partial".into()),
                    None,
                    None,
                    UsageData {
                        input_tokens: 3,
                        output_tokens: 1,
                    },
                ),
                // No turn_complete — simulates crash
            ],
        );

        let history = session.replay_history().expect("replay");
        // Only turn 1's messages should be replayed (2 msgs), turn 2 truncated.
        assert_eq!(history.len(), 2);

        mgr.close("replay-partial").expect("close");
        std::fs::remove_dir_all(&dir).unwrap_or(());
    }

    #[test]
    fn replay_old_log_missing_call_id() {
        let dir = tmp_working_dir();
        let mut mgr = SessionManager::new(&dir);
        let session = mgr
            .create("replay-old", "deepseek-chat", "p")
            .expect("create");
        let now = Utc::now();

        write_log(
            session,
            &[
                LogEntry::user_input(now, 1, "echo test".into()),
                LogEntry::llm_response(
                    now,
                    1,
                    Some("m1".into()),
                    None,
                    None,
                    Some(vec![ToolCallData {
                        id: "call_123".into(),
                        name: "echo".into(),
                        arguments: serde_json::json!({"text": "test"}),
                    }]),
                    UsageData {
                        input_tokens: 10,
                        output_tokens: 5,
                    },
                ),
            ],
        );

        // Append an old-format tool_execution (no call_id field).
        let old_exec = serde_json::json!({
            "kind": "tool_execution",
            "ts": now.to_rfc3339(),
            "turn": 1,
            "data": {
                "tool_call_id": "call_123",
                "name": "echo",
                "arguments": {"text": "test"},
                "result": "test"
            }
        });
        let log_path = session.root().join("events.jsonl");
        {
            use std::io::Write as _;
            let mut file = std::fs::OpenOptions::new()
                .append(true)
                .open(&log_path)
                .expect("open log");
            writeln!(file, "{}", serde_json::to_string(&old_exec).unwrap())
                .expect("write old entry");
        }

        // Then the follow-up response and turn_complete.
        write_log(
            session,
            &[
                LogEntry::llm_response(
                    now,
                    1,
                    Some("m2".into()),
                    Some("echoed: test".into()),
                    None,
                    None,
                    UsageData {
                        input_tokens: 5,
                        output_tokens: 3,
                    },
                ),
                LogEntry::turn_complete(now, 1, "echoed: test".into(), 1),
            ],
        );

        let history = session.replay_history().expect("replay");
        // user + assistant(tool call) + tool result(old log) + assistant(text) = 4
        assert_eq!(history.len(), 4);

        mgr.close("replay-old").expect("close");
        std::fs::remove_dir_all(&dir).unwrap_or(());
    }
}

//! Mandatory filesystem lock for session directories.
//!
//! Uses `fs2::FileExt` for cross-platform file locking. The lock is
//! exclusive and held for the lifetime of the `SessionGuard`.

use std::fs::{File, OpenOptions};
use std::io;
use std::path::{Path, PathBuf};

use fs2::FileExt;

/// Holds an exclusive lock on a session directory's `.lock` file.
///
/// The lock is released when the guard is dropped.
#[derive(Debug)]
pub struct SessionGuard {
    _file: File,
    _path: PathBuf,
}

impl SessionGuard {
    /// Acquire an exclusive lock on `<dir>/.lock`.
    ///
    /// Fails immediately if another process holds the lock.
    pub fn acquire(dir: &Path) -> io::Result<Self> {
        let lock_path = dir.join(".lock");
        let file = OpenOptions::new()
            .create(true)
            .truncate(true)
            .read(true)
            .write(true)
            .open(&lock_path)?;
        file.try_lock_exclusive()?;
        Ok(Self {
            _file: file,
            _path: lock_path,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::PathBuf;

    fn tmp_dir() -> PathBuf {
        let dir = std::env::temp_dir().join(format!("hanihi-lock-test-{}", uuid::Uuid::new_v4()));
        std::fs::create_dir_all(&dir).unwrap();
        dir
    }

    #[test]
    fn acquire_and_drop() {
        let dir = tmp_dir();
        let guard = SessionGuard::acquire(&dir).expect("acquire");
        let lock_path = dir.join(".lock");
        assert!(lock_path.exists());
        drop(guard);
        // After drop the lock file still exists on disk (we don't delete it),
        // but the lock should be released so a second acquire succeeds.
        let _guard2 = SessionGuard::acquire(&dir).expect("second acquire after drop");
        std::fs::remove_dir_all(&dir).unwrap_or(());
    }

    #[test]
    fn exclusive_lock_fails() {
        let dir = tmp_dir();
        let _guard = SessionGuard::acquire(&dir).expect("first acquire");
        let result = SessionGuard::acquire(&dir);
        assert!(result.is_err());
        std::fs::remove_dir_all(&dir).unwrap_or(());
    }
}

